(() => { const data = {"schema":"solar-year.vyboria-reading.v1","author":"ALEX_DOC","language":"ru","source":"IFTHENDZEN_VYBORIA_30D_Solar_Prometei_pack_v0.1.0.zip","sha256":"ae21171c9d57b1594091d629f8c8507f5bda61814469160edaa0bae4e4e641e4","days":[{"day":1,"title":"Я выбираю цель","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Выбери один главный результат на ближайшие 30 дней."},{"heading":false,"text":"Он должен быть понятным и проверяемым."},{"heading":false,"text":"Не:"},{"heading":false,"text":"«Хочу стать лучше»."},{"heading":false,"text":"А:"},{"heading":false,"text":"«Через 30 дней у меня готов работающий прототип приложения»."},{"heading":false,"text":"или:"},{"heading":false,"text":"«Через 30 дней я выполняю четыре тренировки в неделю»."},{"heading":true,"text":"Что может увести"},{"heading":false,"text":"Желание добавить ещё несколько целей:"},{"heading":false,"text":"«И раз уж начали, неплохо бы ещё вот это…»"},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"ЕСЛИ появляется ещё одна важная цель,\nТО записываю её отдельно и возвращаюсь к главной цели этого цикла."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Запиши:"},{"heading":false,"text":"- чего хочу достичь;\n- что будет считаться результатом;\n- как пойму, что цель достигнута."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Тридцать направлений одновременно обычно дают очень насыщенное стояние в итоге."}]},{"day":2,"title":"Я понимаю зачем","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Ответь:"},{"heading":false,"text":"Зачем лично мне нужна эта цель?"},{"heading":false,"text":"Что изменится, когда результат будет получен?"},{"heading":true,"text":"Что может увести"},{"heading":false,"text":"Цель в стиле:"},{"heading":false,"text":"«Надо»."},{"heading":false,"text":"«Давно пора»."},{"heading":false,"text":"«Все нормальные люди уже сделали»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Если не могу объяснить, зачем мне эта цель, уточняю её."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Закончи фразу:"},{"heading":false,"text":"Я выбираю этот путь, потому что..."},{"heading":false,"text":"Одним-двумя честными предложениями."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Когда дорога становится сложнее, хорошо помнить не только куда, но и зачем."}]},{"day":3,"title":"Я вижу исходную точку","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Посмотри, где находишься сейчас."},{"heading":false,"text":"Без ярлыков."},{"heading":false,"text":"Не:"},{"heading":false,"text":"«Я ленивый»."},{"heading":false,"text":"А:"},{"heading":false,"text":"«Когда задача становится непонятной, я часто переключаюсь на что-то проще»."},{"heading":true,"text":"Что может увести"},{"heading":false,"text":"Желание объяснить всё характером:"},{"heading":false,"text":"«Ну я просто такой»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"ЕСЛИ начинаю оценивать себя,\nТО заменяю оценку наблюдаемым фактом."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Запиши:"},{"heading":false,"text":"1. Что уже получается.\n2. Чего пока не хватает.\n3. Где чаще всего останавливаешься.\n4. Что хочешь делать иначе."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Изменять маршрут значительно удобнее, когда знаешь, где находится точка «Вы здесь»."}]},{"day":4,"title":"Я вижу, что меня уводит","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Найди три главных отвлечения."},{"heading":false,"text":"Например:"},{"heading":false,"text":"- телефон;\n- новая идея;\n- мелкие срочные дела;\n- желание всё переделать;\n- сомнение;\n- сложность;\n- усталость."},{"heading":true,"text":"Что важно заметить"},{"heading":false,"text":"Когда отвлечение приходит, одень его в костюм приличных и полезных идей."},{"heading":false,"text":"Оно редко говорит:"},{"heading":false,"text":"«Давай сегодня ничего не сделаем»."},{"heading":false,"text":"Гораздо чаще:"},{"heading":false,"text":"«Сначала быстро посмотрим одну очень полезную вещь»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"ЕСЛИ появляется новое занятие,\nТО спрашиваю:"},{"heading":false,"text":"Оно помогает сегодняшнему шагу или заменяет его?"},{"heading":true,"text":"Действие"},{"heading":false,"text":"Сегодня ничего не запрещаем."},{"heading":false,"text":"Просто замечаем."}]},{"day":5,"title":"Я замечаю первый результат","blocks":[{"heading":false,"text":"Сегодня лёгкий день."},{"heading":false,"text":"Посмотри назад."},{"heading":true,"text":"Три вопроса"},{"heading":false,"text":"- Что за четыре дня стало понятнее?\n- Что впервые заметил в своём поведении?\n- Какой выбор уже помог не свернуть?"},{"heading":true,"text":"Маленькая радость"},{"heading":false,"text":"Сделай что-то приятное:"},{"heading":false,"text":"- прогулка;\n- любимая еда;\n- фильм;\n- встреча;\n- спокойный час без дел."},{"heading":false,"text":"Не как оплату за хорошее поведение."},{"heading":false,"text":"А чтобы отметить:"},{"heading":false,"text":"Первый участок пути пройден."}]},{"day":6,"title":"Я хвалю себя и готовлюсь дальше","blocks":[{"heading":false,"text":"Сегодня ничего не нужно доказывать."},{"heading":true,"text":"Подведи итог"},{"heading":false,"text":"Я выбрал цель.\nЯ понял зачем.\nЯ увидел исходную точку.\nЯ начал замечать, что меня уводит."},{"heading":true,"text":"Похвала себе"},{"heading":false,"text":"Я уже сделал важное: начал видеть свой путь яснее."},{"heading":true,"text":"Вопрос следующей недели"},{"heading":false,"text":"Каким мне нужно научиться быть, чтобы пройти этот путь?"}]},{"day":7,"title":"Я выбираю, каким быть","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Посмотри на свою цель."},{"heading":false,"text":"Какое качество особенно поможет её достигнуть?"},{"heading":false,"text":"Например:"},{"heading":false,"text":"- последовательность;\n- спокойствие;\n- завершение;\n- смелость;\n- терпение;\n- концентрация."},{"heading":true,"text":"Что может увести"},{"heading":false,"text":"Желание улучшить сразу всё."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"На этот цикл выбираю одно главное внутреннее направление."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Закончи:"},{"heading":false,"text":"На пути к своей цели я выбираю быть человеком, который..."},{"heading":false,"text":"Например:"},{"heading":false,"text":"«...завершает главное прежде, чем начинает новое»."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Цель отвечает на вопрос куда."},{"heading":false,"text":"Сегодня мы выбираем как идти."}]},{"day":8,"title":"Я замечаю, что происходит внутри","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Попробуй увидеть цепочку:"},{"heading":false,"text":"событие → мысль → ощущение → эмоция → импульс → действие"},{"heading":false,"text":"Например:"},{"heading":false,"text":"задача сложная\n→ «не понимаю»\n→ напряжение\n→ сомнение\n→ хочется переключиться."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Не подавлять реакцию."},{"heading":false,"text":"Понять её, прожить и выбрать действие, которое позволит стать ближе к цели."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Поймай за день хотя бы два таких момента."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Чувство может быть сильным."},{"heading":false,"text":"Но оно всё равно не обязано получать административный доступ ко всем действиям."}]},{"day":9,"title":"Я нахожу точку выбора","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Ищи момент:"},{"heading":false,"text":"импульс уже появился,\nно действие ещё не произошло."},{"heading":false,"text":"Это и есть точка выбора."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Когда её замечаю:"},{"heading":false,"text":"1. останавливаюсь на несколько секунд;\n2. понимаю, что происходит;\n3. спрашиваю:"},{"heading":false,"text":"Что сейчас приблизит меня к цели?"},{"heading":true,"text":"Действие"},{"heading":false,"text":"Сегодня достаточно поймать одну настоящую точку выбора."}]},{"day":10,"title":"Я заранее выбираю действие","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Создай одно простое правило."},{"heading":false,"text":"Например:"},{"heading":false,"text":"ЕСЛИ замечаю желание переключиться,\nТО записываю новую идею и сначала завершаю текущий шаг."},{"heading":true,"text":"Важно"},{"heading":false,"text":"После «ТО» должно быть действие."},{"heading":false,"text":"Не:"},{"heading":false,"text":"«стану собраннее»."},{"heading":false,"text":"А:"},{"heading":false,"text":"«закрою вкладку и ещё 15 минут работаю над текущей задачей»."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"В сложный момент хорошо иметь готовое решение, а не созывать внутреннее совещание."}]},{"day":11,"title":"Я смотрю на первые выборы","blocks":[{"heading":false,"text":"Сегодня меньше работы."},{"heading":false,"text":"Solar Circle показывает:"},{"heading":false,"text":"- сколько точек выбора замечено;\n- сколько раз удалось остановиться;\n- сколько раз выбрано новое действие."},{"heading":false,"text":"Даже:"},{"heading":false,"text":"заметил 2;\nвыбрал новое 1 раз"},{"heading":false,"text":"— уже результат."},{"heading":true,"text":"Маленькая радость"},{"heading":false,"text":"Сделай что-то приятное."},{"heading":false,"text":"Сегодня отмечаем не идеальность."},{"heading":false,"text":"А факт:"},{"heading":false,"text":"Я стал замечать себя раньше."}]},{"day":12,"title":"Я выбрал направление","blocks":[{"heading":true,"text":"Итог недели"},{"heading":false,"text":"Я понимаю, каким хочу быть.\nЯ вижу привычную реакцию.\nЯ начал замечать точку выбора.\nУ меня появился новый вариант действия."},{"heading":true,"text":"Похвала себе"},{"heading":false,"text":"Раньше между импульсом и действием часто ничего не происходило. Теперь там иногда появляется Я."},{"heading":true,"text":"Следующий этап"},{"heading":false,"text":"Теперь выбор должен начать двигать мою реальную цель."}]},{"day":13,"title":"Я прохожу трудный момент заранее","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Возьми важную задачу дня."},{"heading":false,"text":"Представь:"},{"heading":false,"text":"1. начинаешь;\n2. появляется трудность;\n3. возникает привычное сопротивление;\n4. хочется уйти;\n5. замечаешь это;\n6. делаешь выбранное действие;\n7. продолжаешь."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Не представлять только красивый результат."},{"heading":false,"text":"Репетировать сам момент выбора."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Полезно встретиться со сложным моментом немного раньше, чем он встретится с тобой."}]},{"day":14,"title":"Я начинаю","blocks":[{"heading":true,"text":"Что может увести"},{"heading":false,"text":"«Начну чуть позже»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"ЕСЛИ задача понятна, но я откладываю начало,\nТО выполняю минимальный первый шаг."},{"heading":false,"text":"Например:"},{"heading":false,"text":"- пять минут;\n- один файл;\n- один звонок;\n- один абзац."},{"heading":true,"text":"Цель дня"},{"heading":false,"text":"Не закончить всё."},{"heading":false,"text":"Начать реально."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Иногда самый длинный участок дороги находится между:"},{"heading":false,"text":"«надо начать»"},{"heading":false,"text":"и"},{"heading":false,"text":"«я начал»."}]},{"day":15,"title":"Я остаюсь со сложным","blocks":[{"heading":true,"text":"Что может увести"},{"heading":false,"text":"«Слишком трудно»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Не менять направление."},{"heading":false,"text":"Уменьшить шаг."},{"heading":false,"text":"Спросить:"},{"heading":false,"text":"1. Что именно сложно?\n2. Что из этого я понимаю?\n3. Какой кусок можно сделать сейчас?"},{"heading":true,"text":"Действие"},{"heading":false,"text":"Сделай понятный кусок."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Сложность — хороший повод уменьшить шаг."},{"heading":false,"text":"Не обязательно хороший повод менять цель."}]},{"day":16,"title":"Я завершаю","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Спроси:"},{"heading":false,"text":"Что я могу довести до состояния «готово»?"},{"heading":true,"text":"Если приходит новая идея"},{"heading":false,"text":"Записать."},{"heading":false,"text":"Сохранить."},{"heading":false,"text":"Вернуться."},{"heading":true,"text":"Если хочется бесконечно улучшать"},{"heading":false,"text":"Разделить:"},{"heading":false,"text":"- необходимо сейчас;\n- можно улучшить потом."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Сегодня приоритет — завершение."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Хорошая новая идея вполне способна несколько часов спокойно пожить в списке."}]},{"day":17,"title":"Я вижу доказательство изменения","blocks":[{"heading":false,"text":"Лёгкий день."},{"heading":false,"text":"Найди один настоящий эпизод:"},{"heading":false,"text":"Обычно я бы сделал X.\nНа этот раз заметил момент и сделал Y."},{"heading":false,"text":"Solar Circle сохраняет его:"},{"heading":false,"text":"Мой выбор недели."},{"heading":true,"text":"Маленькая радость"},{"heading":false,"text":"Сегодня можно порадовать себя чуть заметнее."},{"heading":false,"text":"Появилось не намерение измениться."},{"heading":false,"text":"Появилось действие нового Я."}]},{"day":18,"title":"Я вижу половину пути","blocks":[{"heading":false,"text":"Solar Circle показывает:"},{"heading":true,"text":"Моя цель"},{"heading":false,"text":"Что уже выполнено?"},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Что стал замечать раньше?"},{"heading":true,"text":"Моё действие"},{"heading":false,"text":"Что начал делать иначе?"},{"heading":true,"text":"Похвала себе"},{"heading":false,"text":"Я уже не только понимаю, каким хочу быть. У меня появились поступки этого человека."},{"heading":true,"text":"Следующий этап"},{"heading":false,"text":"Теперь я учусь сохранять выбор, даже когда день решил не помогать."}]},{"day":19,"title":"Я действую без нужного настроения","blocks":[{"heading":true,"text":"Что может увести"},{"heading":false,"text":"«Сегодня не хочется»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Не спорить с настроением."},{"heading":false,"text":"Спросить:"},{"heading":false,"text":"Какой минимальный шаг я могу сделать в текущем состоянии?"},{"heading":false,"text":"И сделать его."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Настроение стоит учитывать."},{"heading":false,"text":"Но передавать ему право окончательного решения необязательно."}]},{"day":20,"title":"Я сохраняю направление при усталости","blocks":[{"heading":true,"text":"Что может увести"},{"heading":false,"text":"«Если не могу сделать всё — сегодня ничего»."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Уменьшить объём:"},{"heading":false,"text":"100% невозможно → 50%."},{"heading":false,"text":"50% тяжело → 20%."},{"heading":false,"text":"20% тяжело → минимум."},{"heading":true,"text":"Главное"},{"heading":false,"text":"Сохранить направление."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Трудный день может быть небольшим."},{"heading":false,"text":"Он не обязан становиться нулевым."}]},{"day":21,"title":"Реальность пошла не по плану","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Сравни:"},{"heading":false,"text":"Что я ожидал?"},{"heading":false,"text":"и:"},{"heading":false,"text":"Что произошло на самом деле?"},{"heading":false,"text":"Не называй расхождение поражением. Сначала определи, по какому варианту пошёл день:"},{"heading":false,"text":"- хороший;\n- средний;\n- плохой."},{"heading":true,"text":"Главный вопрос"},{"heading":false,"text":"Я могу сейчас изменить эту ситуацию?"},{"heading":false,"text":"#### Если да"},{"heading":false,"text":"Выбираю конкретное следующее действие."},{"heading":false,"text":"#### Если нет"},{"heading":false,"text":"Принимаю уже произошедший факт и спрашиваю:"},{"heading":false,"text":"Какой мой следующий выбор всё ещё может улучшить путь?"},{"heading":false,"text":"#### Если не понимаю"},{"heading":false,"text":"Разделяю:"},{"heading":false,"text":"- факт;\n- мою интерпретацию;\n- то, на что могу влиять;\n- то, на что не могу влиять."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Плохой результат — не конец пути. Это новая точка выбора."},{"heading":true,"text":"Действие"},{"heading":false,"text":"1. Зафиксировать, что произошло.\n2. Сохранить то, что уже сделано.\n3. Понять, что теперь является новой исходной точкой.\n4. Выбрать следующий лучший доступный шаг."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"План иногда тоже имеет собственное мнение о том, как пройдёт день. Нам важнее не угадать всё заранее, а уметь продолжать после факта."}]},{"day":22,"title":"Я выбираю: действовать или принять","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Отрабатываем одну из главных способностей Выбории."},{"heading":false,"text":"Когда появляется проблема, последовательно спроси:"},{"heading":false,"text":"1. Что произошло фактически?\n2. Можно ли это изменить?\n3. Если можно — что конкретно я сделаю?\n4. Если нельзя — что мне важно принять?\n5. После принятия — какое действие или отношение всё ещё остаётся моим выбором?"},{"heading":true,"text":"Пример"},{"heading":false,"text":"Встречу отменили."},{"heading":false,"text":"Я не могу вернуть уже отменённую встречу."},{"heading":false,"text":"Но могу:"},{"heading":false,"text":"- перенести;\n- отправить материал;\n- использовать освободившееся время;\n- пересобрать следующий шаг."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Когда могу влиять — действую. Когда изменить не могу — принимаю. И в обоих случаях выбор остаётся моей мышцей."},{"heading":true,"text":"Что важно понять"},{"heading":false,"text":"Принятие — не бездействие."},{"heading":false,"text":"Это отказ тратить силы на спор с уже произошедшим фактом и переход к тому, что всё ещё можно выбрать."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Не всё находится в нашей власти. Но даже граница влияния сама становится точкой выбора: действовать там, где можешь, и не воевать с тем, что уже нельзя изменить."}]},{"day":23,"title":"Я вижу, что выдержало","blocks":[{"heading":false,"text":"Сегодня спокойнее."},{"heading":false,"text":"Вспомни:"},{"heading":false,"text":"- устал, но сделал минимум;\n- ошибся, но вернулся;\n- план сорвался, но нашёл следующий шаг;\n- не мог изменить событие, но смог выбрать реакцию."},{"heading":true,"text":"Маленькая радость"},{"heading":false,"text":"Сегодня отмечаем не только результат."},{"heading":false,"text":"А новую способность:"},{"heading":false,"text":"Я умею возвращаться и перестраивать путь."},{"heading":false,"text":"Порадуй себя чем-то небольшим и приятным."}]},{"day":24,"title":"Я умею продолжать","blocks":[{"heading":true,"text":"Итог недели"},{"heading":false,"text":"Я могу двигаться без идеального настроения.\nЯ умею уменьшать шаг.\nЯ могу вернуться после ошибки.\nЯ различаю, где нужно действовать, а где принять факт.\nЯ умею искать следующий лучший доступный путь."},{"heading":true,"text":"Похвала себе"},{"heading":false,"text":"Мне не нужно контролировать всё, чтобы продолжать выбирать своё следующее действие."},{"heading":true,"text":"Следующий этап"},{"heading":false,"text":"Теперь посмотрим, что из нового уже начинает становиться частью меня."}]},{"day":25,"title":"Я замечаю, что стало легче","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Сравни себя с первой неделей."},{"heading":false,"text":"Что теперь требует меньше внутреннего спора?"},{"heading":false,"text":"Например:"},{"heading":false,"text":"- проще начать;\n- проще вернуться;\n- проще не переключаться;\n- проще закончить;\n- проще сделать паузу."},{"heading":true,"text":"Действие"},{"heading":false,"text":"Запиши один конкретный пример."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Изменение иногда сначала заметно не по огромному результату."},{"heading":false,"text":"А по тому, что нужное действие стало немного легче."}]},{"day":26,"title":"Я замечаю, что новое начинает происходить само","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Ищи ситуации:"},{"heading":false,"text":"старый триггер\n→ новая реакция появилась раньше привычной."},{"heading":false,"text":"Например:"},{"heading":false,"text":"новая идея появилась\n→ автоматически записал\n→ продолжил работу."},{"heading":false,"text":"или:"},{"heading":false,"text":"планы нарушились\n→ вместо «всё пропало» появился вопрос\n→ «что я могу сделать теперь?»"},{"heading":true,"text":"Действие"},{"heading":false,"text":"Отметь такой момент в Solar Circle."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"То, что недавно требовало отдельного решения, постепенно может становиться обычным способом действовать."}]},{"day":27,"title":"Я вижу, где ещё нужна тренировка","blocks":[{"heading":true,"text":"Сегодня"},{"heading":false,"text":"Ответь:"},{"heading":false,"text":"В каких условиях старое поведение всё ещё сильнее?"},{"heading":false,"text":"Например:"},{"heading":false,"text":"- сильная усталость;\n- конфликт;\n- давление времени;\n- неопределённость;\n- слишком привлекательное отвлечение;\n- событие, на которое невозможно повлиять."},{"heading":true,"text":"Мой выбор"},{"heading":false,"text":"Не оценивать это как поражение."},{"heading":false,"text":"Записать как следующий участок развития."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Хороший результат месяца — это не отсутствие слабых мест."},{"heading":false,"text":"Это более точная карта себя."}]},{"day":28,"title":"Я проверяю себя самостоятельно","blocks":[{"heading":false,"text":"Сегодня Solar Circle уменьшает дополнительные подсказки."},{"heading":true,"text":"Проверяем"},{"heading":false,"text":"- сам ли замечаю отвлечение;\n- вспоминаю ли своё правило;\n- различаю ли «могу изменить / не могу изменить»;\n- нахожу ли следующий шаг после плохого сценария;\n- возвращаюсь ли к цели без подсказки."},{"heading":true,"text":"Мысль дня"},{"heading":false,"text":"Хороший помощник постепенно напоминает меньше."},{"heading":false,"text":"Потому что человек начинает уметь больше."}]},{"day":29,"title":"Я праздную пройденный путь","blocks":[{"heading":false,"text":"Сегодня никаких больших новых задач."},{"heading":false,"text":"Посмотри:"},{"heading":false,"text":"30 дней назад..."},{"heading":false,"text":"Сейчас..."},{"heading":false,"text":"Сделано..."},{"heading":false,"text":"Достигнуто..."},{"heading":false,"text":"Изменилось..."},{"heading":true,"text":"Маленькая радость"},{"heading":false,"text":"Сегодня можно выбрать что-то приятное специально в честь завершения цикла."},{"heading":false,"text":"Что-то настоящее."},{"heading":false,"text":"Но совершенно не обязано быть дорогим."},{"heading":true,"text":"Главная мысль"},{"heading":false,"text":"Я дошёл сюда не потому, что всё происходило идеально. Я дошёл сюда своими следующими выборами."}]},{"day":30,"title":"Я вижу себя сегодня","blocks":[{"heading":false,"text":"Последний день одновременно завершает один путь и открывает следующий."},{"heading":true,"text":"Моя цель"},{"heading":false,"text":"- Что планировалось?\n- Что выполнено?\n- Что получено?\n- Что осталось?"},{"heading":true,"text":"Мои сценарии"},{"heading":false,"text":"- Сколько раз всё шло лучше ожидания?\n- Сколько — примерно по плану?\n- Сколько — хуже?\n- В скольких плохих сценариях удалось найти полезный следующий шаг?"},{"heading":true,"text":"Моя зона влияния"},{"heading":false,"text":"- Что я научился менять действием?\n- Что научился принимать без лишней борьбы?\n- Где стал лучше различать одно и другое?"},{"heading":true,"text":"Мои действия"},{"heading":false,"text":"- Сколько важных шагов сделал?\n- Что завершил?\n- Что пришлось изменить?\n- От чего правильно отказался?"},{"heading":true,"text":"Мои выборы"},{"heading":false,"text":"- Сколько точек выбора заметил?\n- Сколько раз заметил их до действия?\n- Сколько раз выбрал новый вариант?\n- Какие новые реакции начали возникать сами?"},{"heading":true,"text":"Моё изменение"},{"heading":false,"text":"Закончи:"},{"heading":false,"text":"30 дней назад я чаще..."},{"heading":false,"text":"Сейчас я чаще..."},{"heading":false,"text":"Мне стало легче..."},{"heading":false,"text":"Я начал раньше замечать..."},{"heading":false,"text":"Я научился выбирать..."},{"heading":false,"text":"Когда могу влиять, я чаще..."},{"heading":false,"text":"Когда изменить нельзя, я чаще..."},{"heading":true,"text":"Похвала себе"},{"heading":false,"text":"Мне не нужно было пройти эти 30 дней идеально. Мне нужно было замечать себя, действовать там, где могу влиять, принимать то, что изменить нельзя, выбирать следующий шаг и возвращаться. Я это сделал."},{"heading":false,"text":"И финальный вопрос:"},{"heading":true,"text":"Кем я выбираю быть следующие 30 дней?"}]}]}; if (typeof module !== 'undefined' && module.exports) module.exports = data; globalThis.SolarYearVyboriaReading = data; })();
